  function protText(p) {
    const parts = [];
    if (p & 1) parts.push(pick("読める", "read"));
    if (p & 2) parts.push(pick("書ける", "write"));
    if (p & 4) parts.push(pick("実行できる", "execute"));
    if (!parts.length) return pick("何もできない（わざと空けてある）", "no access (deliberately empty)");
    return parts.join(pick("・", " / "));
  }
