    const refresh = () => {
      const d = app2.viewer.rowData(row);
      if (!d) return null;
      container.replaceChildren();
      renderDetail(app2, sheet, container, d, row, region);
      return d;
    };
    refresh();
    app2.detailRefresh = () => {
      const d = app2.viewer.rowData(row);
      if (d && d.mnemonic != null && !container.dataset.filled) refresh();
    };
