  function prevRow(app2, row) {
    if (row <= 0) return null;
    const d = app2.viewer.rowData(row - 1);
    if (!d || d.mnemonic == null) return null;
    return { mn: d.mnemonic, ops: d.operands || "" };
  }
  function wordValue(hex6) {
    const parts = String(hex6).replace(/\s+/g, "").match(/.{2}/g);
    if (!parts || parts.length !== 4) return null;
    let v = 0;
    for (let i = 3; i >= 0; i--) v = v * 256 + parseInt(parts[i], 16);
    return v >>> 0;
  }
