  async function prepare(app2, box) {
    if (box) box.say(pick("クラスと、その中の値の名前を読んでいます…", "Reading classes and their fields…"));
    await app2.ensureObjc();
    const strings = await app2.ensureStrings((p) => {
      if (box) {
        box.set(p);
        box.say(pick("アプリの中の言葉を集めています…", "Collecting text…"));
      }
    });
    const program = await app2.ensureProgram((p) => {
      if (box) {
        box.set(p);
        box.say(p.phase === "functions" ? pick("関数の切れ目を調べています…", "Finding function boundaries…") : pick("呼び出し関係とデータ参照を調べています…", "Mapping calls and data references…"));
      }
    });
    const shapes = await app2.ensureShapes((p) => {
      if (box) {
        box.set(p);
        box.say(pick("値の増減のしかたを調べています…", "Watching how values change…"));
      }
    });
    return { strings, program, shapes };
  }
  function goalChips(app2, onPick, { recommended = false } = {}) {
    const wrap3 = el("div", "goalchips");
    const shown = recommended ? GOALS.filter((g) => ["hp", "money", "gacha", "level", "network", "anticheat"].includes(g.id)) : GOALS;
    for (const g of shown) {
      const b = button(pick(g.ja, g.en), "goalchip", () => {
        onPick(goalFromPreset(g.id));
      });
      wrap3.append(b);
    }
    return wrap3;
  }
  function queryMissingText(what) {
    switch (what) {
      case "entity":
        return pick(
          "何について知りたいのか（コイン・HP・経験値など）が読み取れませんでした",
          "What to look for (coins, HP, experience…) could not be read from this"
        );
      case "action":
        return pick(
          "どうなる場所を探すのか（増える・減る・決まる など）が書かれていません",
          "What should happen (increases, decreases, is decided…) is not stated"
        );
      case "text":
        return pick("調べたいことを、もう少し書いてください", "Please write a little more");
      default:
        return "";
    }
  }
  function goalInput(app2, onPick) {
    const wrap3 = el("div", "goal-input");
    const field2 = el("div", "field");
    const input2 = el("input");
    input2.type = "search";
    input2.placeholder = pick(
      "例: 戦闘終了時に経験値が増える場所 / コインの増減 / ガチャでレア度を決めているところ",
      "e.g. where experience increases after a battle, coin balance, where gacha rarity is decided"
    );
    input2.autocapitalize = "off";
    input2.autocomplete = "off";
    input2.spellcheck = false;
    const reading = el("div", "goal-reading");
    reading.hidden = true;
    const showReading = (query) => {
      reading.replaceChildren();
      if (!query || !query.text) {
        reading.hidden = true;
        return;
      }
      reading.hidden = false;
      reading.append(el("b", null, pick("こう受け取りました", "Understood as")));
      reading.append(el("span", null, describeQuery(query)));
      const bits = [];
      if (query.entity.terms.length) {
        bits.push(pick("探す言葉: ", "Terms: ") + query.entity.terms.slice(0, 6).join(" / "));
      }
      if (query.dataflow.steps.length) {
        bits.push(pick("期待する形: ", "Expected shape: ") + query.dataflow.steps.join(" → "));
      }
      if (bits.length) reading.append(el("span", "goal-reading-detail", bits.join("　·　")));
      for (const m of query.missing) {
        const text3 = queryMissingText(m);
        if (text3) reading.append(el("span", "goal-reading-missing", "• " + text3));
      }
    };
    const go = () => {
      const query = compileGoal(input2.value);
      const goal = query.goal;
      if (!goal) {
        toast(pick("調べたいことを入力してください。", "Type what you want to look for."));
        return;
      }
      showReading(query);
      onPick(Object.assign({}, goal, { query }));
    };
    input2.addEventListener("keydown", (e) => {
      if (e.key === "Enter") go();
    });
    input2.addEventListener("input", () => {
      if (!input2.value.trim()) {
        reading.hidden = true;
        return;
      }
      showReading(compileGoal(input2.value));
    });
    field2.append(input2, button(pick("探す", "Search"), "chip", go));
    wrap3.append(field2, reading);
    return wrap3;
  }
